    s1, s2 = 1, 0
    t1, t2 = 0, 1
    while r2:
        q = r1 // r2
        r1, r2 = r2, r1 - q * r2
        s1, s2 = s2, s1 - q * s2
        t1, t2 = t2, t1 - q * t2
    return r1, s1


def nCr_mod(n, M):
    C = [0] * (n + 1)
    C[n] = 1
    for i in range(n - 1, -1, -1):
        C[i] = (C[i + 1] * (i + 1)) % M
        if not C[i]:
