#include <bits/stdc++.h>
using namespace std;

pair<long long, long long> gcd_extended(long long a, long long b) {
    long long r1 = a, r2 = b;
    long long s1 = 1, s2 = 0;
    long long t1 = 0, t2 = 1;
    while (r2 != 0) {
        long long q = r1 / r2;
        long long temp;
        temp = r1; r1 = r2; r2 = temp - q * r2;
        temp = s1; s1 = s2; s2 = temp - q * s2;
        temp = t1; t1 = t2; t2 = temp - q * t2;
    }
    return {r1, s1};
}

vector<long long> nCr_mod(long long n, long long M) {
    vector<long long> C(n + 1, 0);
    C[n] = 1;
    for (long long i = n - 1; i >= 0; --i) {
        C[i] = (C[i + 1] * (i + 1)) % M;
        if (C[i] == 0) break;
    }
    return C;
}

long long calculate(long long n, long long M) {
    vector<vector<vector<long long>>> K;
    K.push_back({{1}});
    for (long long i = 0; i < n - 1; ++i) {
        auto &prev_layer = K[i];
        size_t size_prev = prev_layer.size();
        vector<vector<long long>> new_layer(size_prev + i + 1, vector<long long>(i + 2, 0));
        K.push_back(new_layer);
        for (size_t j = 0; j < size_prev; ++j) {
            for (size_t k = 0; k < prev_layer[j].size(); ++k) {
                long long val = prev_layer[j][k];
                for (long long h = 0; h <= i; ++h) {
                    K[i + 1][j + h][k] = (K[i + 1][j + h][k] + val) % M;
                }
                K[i + 1][j + i + 1][i + 1] = (K[i + 1][j + i + 1][i + 1] + val) % M;
            }
        }
    }
    vector<long long> C = nCr_mod(n, M);
    long long total = 0;
    for (long long i = 1; i < n; ++i) {
        auto &layer = K[i];
        size_t ni = layer.size();
        size_t mi = layer[0].size();
        vector<vector<long long>> S(ni, vector<long long>(mi, 0));
        for (size_t j = 0; j < ni; ++j) {
            for (size_t k = 0; k < mi; ++k) {
                S[j][k] = layer[j][k];
            }
        }
        for (size_t j = 0; j < ni; ++j) {
            for (int k = mi - 2; k >= 0; --k) {
                S[j][k] = (S[j][k] + S[j][k + 1]) % M;
            }
        }
        for (size_t j = 1; j < ni; ++j) {
            for (size_t k = 0; k < mi; ++k) {
                S[j][k] = (S[j][k] + S[j - 1][k]) % M;
            }
        }
        long long sum_i = 0;
        for (size_t j = 1; j < ni; ++j) {
            for (size_t k = 0; k + 1 < mi; ++k) {
                sum_i += (layer[j][k] * S[j - 1][k + 1]) % M;
                sum_i %= M;
            }
        }
        long long c = C[i + 1];
        sum_i = (sum_i * c) % M;
        total = (total + sum_i) % M;
    }
    return total;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
